from pathlib import Path
import shutil
root=Path(__file__).parent
out=root/'_site'
shutil.copytree(root/'public',out,dirs_exist_ok=True)
base='/franchise-pravo/'
for p in out.rglob('*.html'):
 s=p.read_text().replace('<body>','<body data-static="true">')
 s=s.replace('Предпросмотр для Никиты · <a href="/privacy/">заявки остаются на этом устройстве</a>','Версия для просмотра · <a href="/privacy/">приём обращений ещё не подключён</a>')
 s=s.replace('Согласен на локальное сохранение тестовой заявки.','Понимаю, что обращение будет скачано на моё устройство.')
 s=s.replace('Сохранить тестовую заявку','Скачать моё обращение')
 s=s.replace('Режим предпросмотра. Заявка сохранится на этом устройстве. Юристу и в CRM она не отправляется. Используйте тестовые данные.','Можно заполнить форму и скачать текст обращения. Данные не отправляются юристу и не сохраняются на сервере.')
 s=s.replace('Обработка данных в предпросмотре','Обработка данных в версии для просмотра')
 s=s.replace('Это локальная версия сайта для проверки. Тестовая заявка сохраняется на компьютере, где запущен сайт. Передача юристу, в CRM и сторонние системы не подключена.','Это версия сайта для просмотра. Форма позволяет скачать текст обращения на ваше устройство. Передача юристу, в CRM и сторонние системы не подключена.')
 s=s.replace('Выбранная ситуация, имя, контакт, название клуба и описание, если вы их указали, дата заявки и отметка согласия. Используйте вымышленные тестовые данные и не вводите документы или конфиденциальные сведения.','В скачиваемый файл попадут выбранная ситуация, имя, контакт, название клуба и описание, если вы их укажете. Эти поля обрабатываются в вашем браузере и не передаются серверу.')
 s=s.replace('Тестовые заявки доступны владельцу этого компьютера в локальном файле проекта. Он может удалить их после проверки. Внешних аналитических сервисов и рекламных трекеров в этой версии нет.','Скачанный файл хранится на вашем устройстве до удаления. Код формы не сохраняет введённые поля в cookies или локальном хранилище. Рекламных трекеров нет. При открытии сайта хостинг GitHub Pages получает обычные технические данные запроса, например IP-адрес.')
 s=s.replace('Сайт находится в локальном предпросмотре. Действующие реквизиты исполнителя и реальный канал приёма заявок ещё не подключены. Отправленная тестовая форма никому не передаётся.','Это версия сайта для просмотра. Действующие реквизиты исполнителя и канал приёма заявок ещё не подключены. Форма скачивает подготовленное обращение на ваше устройство и никому его не отправляет.')
 s=s.replace('href="/','href="'+base).replace('src="/','src="'+base)
 p.write_text(s)
(out/'.nojekyll').touch()
print(out)
